{"code": "import pandas as pd, numpy as np
import statsmodels.formula.api as smf
df = pd.read_csv('data/explore.csv')
exps = ['anneal_temp','cool_rate','carbon_pct','chromium_pct','grain_size','humidity','press_time','nickel_pct','porosity','cure_hours']
for e in exps:
    cs=[]
    for lab,g in df.groupby('lab'):
        cs.append(g[e].corr(g['tensile_mpa']))
    print(f"{e:14s} within-lab corrs: {[round(c,3) for c in cs]}  mean={np.mean(cs):.3f}")
"}
